SELECT rg.name, COUNT(o.order_id) FROM orders o JOIN customer_addresses a USING (address_id) JOIN cities c ON c.city_id = a.city_id JOIN regions rg ON rg.region_id = c.region_id WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-03-01 00:00:00' AND o.order_at < TIMESTAMP '2025-04-01 00:00:00' AND rg.region_id IN (1, 2) GROUP BY 1
